const configRow = $input.first()?.json ?? {};
const workflowInput = $('When Executed by Another Workflow').first().json;
const rowFound = configRow.key === 'idempotency_enabled';

// Fail safe: only an explicit Boolean false disables the guard.
const enabled = rowFound ? configRow.enabled !== false : true;

return [{
  json: {
    ...workflowInput,
    config: {
      ...(workflowInput.config ?? {}),
      idempotency_enabled: enabled,
      idempotency_config_source: 'data_table',
      idempotency_config_row_found: rowFound,
    },
  },
}];

return $input.all().map((item, index) => ({
  json: {
    ...item.json,
    idempotency: {
      enabled: false,
      key: null,
      claim_action: 'bypassed',
      should_continue: true,
      outcome: 'continue',
    },
  },
  pairedItem: { item: index },
}));

const { createHash } = require('crypto');

function stableValue(value) {
  if (value === undefined || value === null) return '';
  return String(value).trim();
}

return $input.all().map((item, index) => {
  const payload = item.json;
  const email = stableValue(payload.lead?.email_normalized).toLowerCase();
  const phone = stableValue(payload.lead?.phone_normalized);
  const submissionReference = stableValue(payload.context?.submission_reference);
  const source = `${email}|${phone}|${submissionReference}`;
  const key = createHash('sha256').update(source, 'utf8').digest('hex');

  return {
    json: {
      ...payload,
      idempotency: {
        key,
      },
    },
    pairedItem: { item: index },
  };
});

return $input.all().map((item, index) => {
  const claim = item.json;
  const payload = claim.workflow_payload;

  if (!payload || typeof payload !== 'object') {
    throw new Error('Idempotency claim did not return the workflow payload');
  }

  return {
    json: {
      ...payload,
      idempotency: {
        ...payload.idempotency,
        claim_action: claim.claim_action,
        stored_correlation_id: claim.stored_correlation_id,
        stored_status: claim.stored_status,
        previous_result: claim.previous_result ?? null,
        previous_error: claim.previous_error ?? null,
      },
    },
    pairedItem: { item: index },
  };
});

const OUTCOMES = {
  claimed: 'continue',
  completed: 'return_previous_result',
  processing: 'accepted_in_progress',
  failed: 'authorized_safe_replay_required',
};

return $input.all().map((item, index) => {
  const payload = item.json;
  const claimAction = payload.idempotency?.claim_action;
  const outcome = OUTCOMES[claimAction];

  if (!outcome) {
    throw new Error(`Unsupported idempotency claim action: ${claimAction}`);
  }

  return {
    json: {
      ...payload,
      idempotency: {
        ...payload.idempotency,
        enabled: true,
        should_continue: claimAction === 'claimed',
        outcome,
      },
    },
    pairedItem: { item: index },
  };
});
